-- Phase B — state models, supporting registries and the 30 canonical workflows
--
-- Generated by scripts/phase_b/gen_migration.mjs from the checksummed package under
-- docs/phase-b/package/.  Do not hand-edit: scripts/checks/phase_b_migration_matches_package.test.mjs
-- regenerates this file and fails on any difference.
--
-- This file writes registry rows only.  It creates no cron job, no provider route, no
-- autonomous executor and no business record.

set lock_timeout = '8s';
set statement_timeout = '600s';


-- ---- workflow and step state models ----
on conflict (state) do update set definition = excluded.definition, terminal = excluded.terminal;
on conflict (state) do update set definition = excluded.definition, terminal = excluded.terminal;

-- ---- allowed transitions; anything not listed here is refused ----
on conflict (from_state, to_state) do update set condition = excluded.condition;
on conflict (from_state, to_state) do update set condition = excluded.condition;

-- ---- dynamic actors ----
-- Every one of these is deliberately NOT a standing role.  may_be_accountable is false for all
-- but the founder and the category overlay; the overlay's scope is narrowed further by
-- fn_phase_b_owner_guard to an analysis step inside W05, W06, W07, W10 or W14.
on conflict (actor_token) do update set actor_type = excluded.actor_type, meaning = excluded.meaning, resolution_rule = excluded.resolution_rule, may_be_accountable = excluded.may_be_accountable;

-- ---- SLA policies (internal operational targets, not public promises) ----
on conflict (sla_policy_id) do update set name = excluded.name, workflow_scope = excluded.workflow_scope, target = excluded.target, classification = excluded.classification, breach_action = excluded.breach_action;

-- ---- business objects ----
on conflict (object_id) do update set governing_workflow_id = excluded.governing_workflow_id, accountable_role_id = excluded.accountable_role_id, definition = excluded.definition, record_policy = excluded.record_policy, mutation_rule = excluded.mutation_rule;

-- ---- business rules ----
on conflict (rule_id) do update set rule_name = excluded.rule_name, rule_text = excluded.rule_text, workflow_scope = excluded.workflow_scope, rule_type = excluded.rule_type;

-- ---- gates ----
on conflict (gate_id) do update set gate_name = excluded.gate_name, workflow_scope = excluded.workflow_scope, required_evidence = excluded.required_evidence, pass_result = excluded.pass_result, fail_result = excluded.fail_result, gate_type = excluded.gate_type;

-- ---- founder boundaries ----
on conflict (boundary_id) do update set boundary_name = excluded.boundary_name, definition = excluded.definition, workflow_scope = excluded.workflow_scope, decision_owner = excluded.decision_owner, phase_b_enforcement = excluded.phase_b_enforcement;

-- ---- the 30 canonical workflows ----
-- accountable_role_id and independent_reviewer_role_id hold CANONICAL role_ids; the package's
-- own spelling is kept in package_accountable_token so the crosswalk stays readable against
-- the document the founder approved.
on conflict (workflow_id) do update set workflow_name = excluded.workflow_name, domain = excluded.domain, criticality = excluded.criticality, profile = excluded.profile, primary_object = excluded.primary_object, purpose = excluded.purpose, accountable_role_id = excluded.accountable_role_id, package_accountable_token = excluded.package_accountable_token, contributors = excluded.contributors, independent_reviewer_role_id = excluded.independent_reviewer_role_id, start_event = excluded.start_event, required_end_state = excluded.required_end_state, founder_boundary = excluded.founder_boundary, allowed_terminal_states = excluded.allowed_terminal_states, reopen_allowed = excluded.reopen_allowed;

-- ---- errata against the committed package ----
on conflict (package_file, record_id) do update set defect = excluded.defect, evidence = excluded.evidence, correction = excluded.correction, rationale = excluded.rationale;
