insert into public.phase_b_business_rule (rule_id, rule_name, rule_text, workflow_scope, rule_type) values
  ('BR-001', 'One accountable owner', 'Every workflow and required workflow step has exactly one accountable owner.', 'all', 'hard'),
  ('BR-002', 'Creator/reviewer separation', 'A creator cannot be the sole final independent reviewer of the same consequential output.', 'all', 'hard'),
  ('BR-003', 'Founder-reserved boundaries', 'No AI role may approve or alter a founder-reserved decision.', 'W01;W02;W03;W15;W16;W21;W27;W28;W30', 'hard'),
  ('BR-004', 'Canonical identity only for new work', 'All new workflow ownership and state writes use canonical active identities; aliases are input/history compatibility only.', 'all', 'hard'),
  ('BR-005', 'Inactive identity cannot act', 'Inactive, merged-away or unknown identities cannot own or execute current work.', 'all', 'hard'),
  ('BR-006', 'Valid transition only', 'Business objects and workflow runs may move only through declared state transitions.', 'all', 'hard'),
  ('BR-007', 'Prerequisite enforcement', 'A step cannot start or complete before all required predecessor outputs and gates pass.', 'all', 'hard'),
  ('BR-008', 'Complete handoff packet', 'A receiving owner may reject an incomplete handoff; incomplete handoffs cannot be treated as accepted.', 'all', 'hard'),
  ('BR-009', 'Closure criteria required', 'No workflow may close while a mandatory step, blocker, obligation or handoff remains unresolved.', 'all', 'hard'),
  ('BR-010', 'History preservation', 'Completed decisions, reviews, acceptances, revisions and attempts are never overwritten; changes create new versions/records.', 'all', 'hard'),
  ('BR-011', 'No customer identity before reveal', 'Supplier-facing payloads, files, portal views and notifications may not contain customer identity before the approved reveal state.', 'W08;W12;W13;W14;W15', 'hard'),
  ('BR-012', 'Approved safe package required', 'No supplier assignment or notification may be created without an approved immutable supplier-safe package.', 'W08;W12;W13', 'hard'),
  ('BR-013', 'Quote-ready inquiry required', 'No inquiry may be dispatched while mandatory qualification, route, document or readiness blockers remain.', 'W05;W06;W07;W12', 'hard'),
  ('BR-014', 'Confirmed route required for dispatch', 'Proposed, ambiguous, rejected or excluded routes cannot independently authorize supplier dispatch.', 'W06;W12', 'hard'),
  ('BR-015', 'Supplier approval required', 'Only currently approved, eligible suppliers may receive a dispatch assignment.', 'W10;W12;W14', 'hard'),
  ('BR-016', 'Idempotent assignment', 'One supplier may receive at most one assignment for the same inquiry version and dispatch scope.', 'W12', 'hard'),
  ('BR-017', 'Notification count equals successful assignments', 'Refused or failed assignments are not counted as contacted and do not create success notifications.', 'W12;W13', 'hard'),
  ('BR-018', 'Supplier quote remains supplier-authored', 'The platform may normalize for comparison but cannot alter the supplier''s original quotation revision.', 'W14;W15', 'hard'),
  ('BR-019', 'Published quote visibility only', 'Customers may see only their own approved/published quotation comparison versions.', 'W14;W15', 'hard'),
  ('BR-020', 'Payment before reveal', 'Supplier contact identity is revealed only after the founder-approved payment state is confirmed and reconciled.', 'W15;W16', 'hard'),
  ('BR-021', 'Three percent reveal policy', 'The reveal charge uses the current founder-approved reveal-fee policy; changing the percentage is founder-reserved.', 'W15;W16', 'founder'),
  ('BR-022', 'No supplier commission', 'QuotesDone does not charge suppliers a job-success commission unless the founder changes the commercial model.', 'W09;W16;W17;W27', 'founder'),
  ('BR-023', 'Founding supplier exemption', 'The founder-approved founding-supplier exemption is permanent for eligible suppliers and cannot be recalculated by mutable counts.', 'W09;W10;W16;W27', 'founder'),
  ('BR-024', 'Subscription terms founder-reserved', 'Supplier subscription amount, start date and exemption policy are founder-reserved.', 'W09;W16;W27', 'founder'),
  ('BR-025', 'Exact terms acceptance', 'Terms acceptance must reference the exact displayed version and hash and remain append-only.', 'W04;W09', 'hard'),
  ('BR-026', 'No certificate before acceptance', 'No legal acceptance certificate may be generated before a valid acceptance record exists.', 'W04;W09', 'hard'),
  ('BR-027', 'Evidence provenance', 'Every extracted document fact, normalization, score and review finding must retain source/version provenance.', 'W05;W07;W08;W10;W14;W25;W26', 'hard'),
  ('BR-028', 'Never infer unsupported technical facts', 'Missing technical, quantity, regulatory or document facts remain unknown and trigger clarification/escalation.', 'W05;W06;W07;W14', 'hard'),
  ('BR-029', 'Document conflict preserved', 'Conflicting evidence is preserved and cannot be silently overwritten by lower-authority evidence.', 'W05;W07;W10;W14', 'hard'),
  ('BR-030', 'Independent supplier verification', 'Supplier onboarding cannot approve its own supplier; verification is an independent review.', 'W09;W10', 'hard'),
  ('BR-031', 'Payment execution and reconciliation separation', 'The effective identity executing a monetary action cannot independently reconcile/approve that same action.', 'W16;W17;W27', 'hard'),
  ('BR-032', 'Provider event idempotency', 'External payment/refund events are unique, authenticated and safe under duplicate or out-of-order delivery.', 'W16;W17', 'hard'),
  ('BR-033', 'Unknown monetary state is visible', 'Unknown, conflicting or unreconciled monetary states are blocked/quarantined and cannot be treated as success.', 'W16;W17;W27', 'hard'),
  ('BR-034', 'Consent and suppression enforcement', 'Notifications must respect consent, opt-out, suppression, frequency and sender-policy rules.', 'W13;W18;W19;W20', 'hard'),
  ('BR-035', 'Only approved asset revision publishes', 'Marketing or operational content may publish only the exact independently approved revision.', 'W13;W20', 'hard'),
  ('BR-036', 'Actual artifact review', 'Visual/video/file review must inspect the actual final artifact, not only the prompt or brief.', 'W08;W20;W22;W24', 'hard'),
  ('BR-037', 'No self-certification', 'An agent, department or builder cannot independently certify its own consequential behavior or change.', 'W23;W24;W30', 'hard'),
  ('BR-038', 'Release independence', 'Product/engineering/AI implementers cannot issue the final release go/no-go.', 'W22;W23;W24', 'hard'),
  ('BR-039', 'Rollback readiness', 'No consequential production release is approved without a defined and executable rollback/recovery path.', 'W24;W29', 'hard'),
  ('BR-040', 'Metric definition consistency', 'Reports and forecasts use canonical metric definitions and source lineage.', 'W02;W03;W11;W20;W25;W27', 'hard'),
  ('BR-041', 'Activity is not outcome', 'Managers may not declare success solely from activity or vanity metrics when a business outcome is defined.', 'W02;W03;W11;W18;W19;W20;W25;W30', 'hard'),
  ('BR-042', 'Uncertainty explicit', 'Analysis and decisions must distinguish fact, assumption, inference, confidence and unresolved uncertainty.', 'W02;W05;W06;W14;W21;W25;W28', 'hard'),
  ('BR-043', 'No silent exception', 'Policy exceptions require an explicit authorized decision and cannot bypass privacy, safety or founder boundaries.', 'all', 'hard'),
  ('BR-044', 'Timers have escalation', 'Every externally waiting or time-bound step has a deadline, reminder/escalation owner and terminal state.', 'all', 'hard'),
  ('BR-045', 'Retry is a new attempt', 'Retries preserve the failed first attempt and use a new attempt record linked to the original.', 'W13;W16;W17;W24;W29', 'hard'),
  ('BR-046', 'Cancelled is not deleted', 'Cancellation preserves the business record, reason, authority and prior evidence.', 'all', 'hard'),
  ('BR-047', 'Organization change reopens Phase A', 'Role, department, reporting or reviewer changes require a formal Phase A change request and founder approval.', 'W30', 'founder'),
  ('BR-048', 'Category overlays cannot dispatch', 'Category overlays provide qualification and comparison expertise but cannot approve suppliers, dispatch, reveal identity or change policy.', 'W05;W06;W07;W12;W14', 'hard'),
  ('BR-049', 'One inquiry owner remains accountable', 'Specialist and document handoffs do not transfer overall inquiry accountability away from RFQ Qualification Manager unless an explicit approved workflow says so.', 'W05;W06;W07', 'hard'),
  ('BR-050', 'One comparison source of truth', 'Customer comparison uses the canonical normalized quote records and published version, not multiple conflicting comparison implementations.', 'W14;W15', 'hard'),
  ('BR-051', 'One dispatch source of truth', 'All supplier assignments and notifications originate from the canonical W12 dispatch batch.', 'W12;W13', 'hard'),
  ('BR-052', 'One payment source of truth', 'Reveal payment, billing and reconciliation use the canonical transaction lifecycle and not parallel monetary states.', 'W15;W16;W17;W27', 'hard'),
  ('BR-053', 'No workflow activation in Phase B', 'Phase B may define and reconcile workflows but cannot activate new automation, provider calls or autonomous execution.', 'all', 'phase_boundary'),
  ('BR-054', 'Zero paid inference in Phase B', 'Phase B uses no OpenRouter or paid model calls.', 'all', 'phase_boundary')
insert into public.phase_b_gate (gate_id, gate_name, workflow_scope, required_evidence, pass_result, fail_result, gate_type) values
  ('GATE-001', 'Phase A baseline frozen', 'ALL', 'Phase A founder-approved tag, fingerprints and registries exist.', 'Proceed without changing organization.', 'Stop and create formal Phase A change request.', 'hard'),
  ('GATE-002', 'Canonical active owner', 'ALL', 'Step owner resolves to one active canonical role or permitted overlay.', 'Step may be assigned.', 'Block assignment.', 'hard'),
  ('GATE-003', 'One accountable owner', 'ALL', 'Exactly one accountable owner for workflow and step.', 'Proceed.', 'Reject multiply owned/unowned step.', 'hard'),
  ('GATE-004', 'Creator-reviewer separation', 'ALL', 'Creator and final independent reviewer resolve to different effective identities.', 'Review may count.', 'Reject review and reassign reviewer.', 'hard'),
  ('GATE-005', 'Founder boundary', 'ALL', 'Decision is within delegated authority or founder approval exists.', 'Proceed.', 'Block and escalate to founder.', 'hard'),
  ('GATE-006', 'Valid workflow transition', 'ALL', 'Requested transition is declared and prerequisites are satisfied.', 'Apply transition.', 'Reject transition.', 'hard'),
  ('GATE-007', 'Complete handoff', 'ALL', 'Required packet, source version, blockers and requested action are present.', 'Receiver may accept.', 'Reject back to sender with reason.', 'hard'),
  ('GATE-008', 'Closure completeness', 'ALL', 'All mandatory steps, obligations and blockers are closed/handed off.', 'Close workflow.', 'Block closure.', 'hard'),
  ('GATE-009', 'Exact terms acceptance', 'W04;W09', 'Displayed version/hash and acceptance evidence match.', 'Activate/submit.', 'Block account progression.', 'hard'),
  ('GATE-010', 'Inquiry route evidence', 'W05;W06', 'Active route is confirmed with sufficient evidence.', 'Use route requirements.', 'Keep route proposed/blocked.', 'hard'),
  ('GATE-011', 'Inquiry quote readiness', 'W05', 'Mandatory qualification fields and evidence pass; no unresolved blocker.', 'Create qualified snapshot.', 'Block dispatch path.', 'hard'),
  ('GATE-012', 'Document usability', 'W07', 'Document is supported, readable, owned and safe for processing.', 'Process document.', 'Quarantine/reject.', 'hard'),
  ('GATE-013', 'Supplier-safe approval', 'W08;W12', 'Exact brief and file revisions independently pass privacy/fidelity review.', 'Mark dispatch eligible.', 'Block dispatch.', 'hard'),
  ('GATE-014', 'Supplier verification', 'W10;W12;W14', 'Supplier is currently approved and capability evidence supports scope.', 'Include supplier.', 'Exclude/block.', 'hard'),
  ('GATE-015', 'Dispatch idempotency', 'W12', 'No existing assignment for same supplier, inquiry version and dispatch scope.', 'Create assignment.', 'Return existing/refuse duplicate.', 'hard'),
  ('GATE-016', 'Notification eligibility', 'W13', 'Assignment exists, template approved, consent/suppression pass.', 'Attempt delivery.', 'Suppress/block.', 'hard'),
  ('GATE-017', 'Quotation completeness', 'W14', 'Mandatory commercial/technical fields and provenance pass.', 'Approve for comparison.', 'Hold/exclude.', 'hard'),
  ('GATE-018', 'Comparison publication', 'W15', 'Comparison is approved, customer-owned and visibility/privacy policy passes.', 'Publish.', 'Block publication.', 'hard'),
  ('GATE-019', 'Payment reconciliation', 'W15;W16', 'Provider, transaction, invoice and reconciliation agree on success.', 'Authorize reveal.', 'Keep reveal blocked/open exception.', 'hard'),
  ('GATE-020', 'Refund authority and idempotency', 'W17', 'Approved case decision and unique financial action key exist.', 'Execute once.', 'Block/return existing.', 'hard'),
  ('GATE-021', 'Marketing artifact approval', 'W03;W20', 'Exact final asset passes brand and independent artifact review.', 'Publish approved revision.', 'Reject/return correction.', 'hard'),
  ('GATE-022', 'Product acceptance', 'W22', 'Requirement, UX, backend, frontend and test acceptance are complete.', 'Create release candidate.', 'Return to owner.', 'hard'),
  ('GATE-023', 'AI independent evaluation', 'W23', 'Independent model and workflow evaluations pass without answer-key leakage.', 'Handoff release candidate.', 'Block change.', 'hard'),
  ('GATE-024', 'Release readiness', 'W24', 'Tests, security, AI (if relevant), rollback and operations pass.', 'Issue go decision.', 'No-go/rollback.', 'hard'),
  ('GATE-025', 'Data integrity', 'W25', 'Metric/source definitions, lineage and quality pass.', 'Publish intelligence.', 'Reject/correct.', 'hard'),
  ('GATE-026', 'Knowledge validation', 'W26', 'Independent source/freshness/contradiction review passes.', 'Publish runtime-eligible version.', 'Reject/keep draft.', 'hard'),
  ('GATE-027', 'Financial close integrity', 'W27', 'Critical reconciliations, control exceptions and tax coordination pass.', 'Close/report.', 'Block close.', 'hard'),
  ('GATE-028', 'Legal-risk authority', 'W28', 'Legal/compliance/risk review complete and founder gate satisfied where required.', 'Proceed under controls.', 'Block/escalate.', 'hard'),
  ('GATE-029', 'Incident recovery verification', 'W29', 'Service/data/security verification passes after recovery.', 'Close incident/unrestrict service.', 'Keep open/restrict/rollback.', 'hard'),
  ('GATE-030', 'Capability restoration', 'W30', 'Independent verification passes and critical risk is resolved.', 'Restore role/capability.', 'Continue restriction/reassign.', 'hard'),
  ('GATE-031', 'Zero paid inference', 'ALL', 'OpenRouter and paid provider call counts are zero during Phase B.', 'Continue Phase B.', 'Stop phase and report breach.', 'phase_boundary'),
  ('GATE-032', 'No workflow activation', 'ALL', 'No new cron, autonomous executor, provider route or live workflow is activated by Phase B.', 'Deploy structural registry only.', 'Rollback activation change.', 'phase_boundary')
insert into public.phase_b_founder_boundary (boundary_id, boundary_name, definition, workflow_scope, decision_owner, phase_b_enforcement) values
  ('FDR-001', 'Equity and ownership', 'Equity, ownership, cap table, valuation, fundraising, investor admission, sale, merger or winding-up.', 'W01;W21;W27;W28', 'founder', 'No operational role may approve or execute.'),
  ('FDR-002', 'Commercial pricing model', 'Reveal fee, supplier subscription price/start, founding exemption and supplier commission policy.', 'W04;W09;W15;W16;W17;W27;W28', 'founder', 'Systems may calculate only from approved configuration.'),
  ('FDR-003', 'Company revenue objective', 'AED 1,000,000 revenue target and target date.', 'W01;W02;W03;W25;W27', 'founder', 'Management may operationalize but not replace.'),
  ('FDR-004', 'Country and marketplace model', 'Country entry/exit, material marketplace-model change or change to who pays whom.', 'W01;W21;W28', 'founder', 'Strategy may propose; no execution before approval.'),
  ('FDR-005', 'Company identity and permanent policy', 'Company name, brand ownership, core positioning and permanent material policy.', 'W01;W03;W20;W28', 'founder', 'Departments operate within approved policy.'),
  ('FDR-006', 'Spending above authority', 'Spend above approved budgets or unbudgeted commitment above founder threshold.', 'W01;W02;W03;W21;W27', 'founder', 'CFO/CEO escalate with impact.'),
  ('FDR-007', 'Binding legal commitments', 'Legal commitments outside approved templates, limits and delegated authority.', 'W21;W28', 'founder', 'General Counsel blocks until approval.'),
  ('FDR-008', 'Senior human/equity compensation', 'Equity compensation and senior human commitments outside approved plans.', 'W30', 'founder', 'Agent workforce may propose only.'),
  ('FDR-009', 'Consequential autonomy activation', 'Production activation of consequential autonomy where founder approval is required.', 'W23;W24;W30', 'founder', 'No phase may activate without explicit approval.'),
  ('FDR-010', 'Permanent material risk acceptance', 'Permanent acceptance of material legal, financial, security, privacy or reputational risk.', 'W17;W24;W28;W29', 'founder', 'Risk may recommend; founder decides.')
