  ('W01', 'Founder mandate to company objectives', 'executive', 'high', 'governance_cycle', 'company_objective', 'Convert the founder mandate into approved company objectives, department mandates and accountable execution boundaries.', 'ceo', 'ceo', array['chief_of_staff','corporate_performance_director','strategy_director']::text[], 'founder', 'Founder mandate', 'Approved company objectives and department mandates', 'Founder approves reserved decisions', 'completed; cancelled; superseded', 'yes_with_new_version'),
