  ('W04', 'Customer registration and onboarding', 'customer', 'high', 'case_workflow', 'customer_account', 'Create a verified customer account with valid acceptance evidence and guide the customer to a usable first inquiry.', 'customer_onboarding', 'customer_onboarding_specialist', array['customer_support','communications_manager']::text[], 'compliance_and_privacy_officer', 'New invited/organic customer', 'Verified, accepted, usable customer account', 'Terms/policy remain founder-approved', 'completed; cancelled; superseded; failed; expired', 'yes_with_new_version'),
  ('W05', 'Inquiry intake and qualification', 'marketplace', 'critical', 'qualification_cycle', 'inquiry', 'Convert a customer request into a structured, legitimate and quote-ready inquiry or an explicit blocked/clarification state.', 'rfq_qualification_manager', 'rfq_qualification_manager', array['inquiry_router','category overlay','document_intelligence_manager']::text[], 'inquiry_quality_analyst', 'Customer starts inquiry', 'Structured quote-ready or explicitly blocked inquiry', 'No dispatch before readiness/privacy gates', 'completed; cancelled; superseded; failed; expired', 'yes_with_new_version'),
  ('W06', 'Category routing', 'marketplace', 'critical', 'classification_cycle', 'inquiry_route_set', 'Determine and confirm the correct category/route set without silently activating uncertain scope.', 'inquiry_router', 'inquiry_router', array['rfq_qualification_manager','category overlays','broad domain specialists']::text[], 'inquiry_quality_analyst', 'New or changed inquiry evidence', 'Confirmed route set or clarification request', 'No silent uncertain activation', 'completed; cancelled; superseded; failed; expired', 'yes_with_new_version'),
