  ('W09', 'Supplier onboarding', 'supplier', 'high', 'onboarding_cycle', 'supplier_account', 'Collect and validate the supplier profile, capabilities, documents, terms and verification submission.', 'supplier_onboarding_specialist', 'supplier_onboarding_specialist', array['communications_manager','document_intelligence_manager']::text[], 'supplier_verification', 'Supplier invitation/registration', 'Complete verification file', 'No self-approval', 'completed; cancelled; superseded; failed; expired', 'yes_with_new_version'),
  ('W10', 'Supplier verification', 'supplier', 'critical', 'independent_review_cycle', 'supplier_verification_case', 'Issue an independent, evidence-based supplier approval, correction, refusal or suspension decision.', 'supplier_verification', 'supplier_verification_reviewer', array['supplier_onboarding_specialist','fraud_analyst','compliance_and_privacy_officer']::text[], 'risk_and_governance_manager', 'Complete/reviewable supplier file', 'Independent approve/refuse/correct decision', 'No approval without evidence', 'completed; cancelled; superseded; rejected', 'yes_with_new_version'),
  ('W11', 'Supplier coverage and acquisition gaps', 'supplier', 'medium', 'improvement_cycle', 'supplier_coverage_case', 'Measure supplier liquidity gaps and create prioritized acquisition targets tied to inquiry demand and revenue.', 'supplier_coverage', 'supplier_coverage_liquidity_specialist', array['supplier_intelligence_analyst','business_development','category_curator']::text[], 'marketplace_director', 'Coverage/liquidity KPI miss', 'Prioritized supplier acquisition target', 'No unapproved outreach/spend', 'completed; cancelled; superseded', 'yes_with_new_version'),
