  ('W13', 'Supplier notification delivery', 'communications', 'high', 'delivery_cycle', 'notification', 'Deliver approved messages through permitted channels with consent, suppression, retry and terminal-state handling.', 'lifecycle_channel_operations', 'lifecycle_channel_operations_specialist', array['communications_manager','supplier_matching_dispatch_operator']::text[], 'compliance_and_privacy_officer', 'Approved queued notification', 'Delivered/failed/suppressed state', 'Consent and sender policy enforced', 'completed; cancelled; superseded; failed; expired', 'yes_with_new_version'),
