  ('W17', 'Refund, dispute and fraud', 'risk', 'critical', 'case_workflow', 'refund_dispute_case', 'Resolve refund, dispute and fraud cases through evidence, authority, execution, reconciliation and appeal paths.', 'trust_and_safety_manager', 'trust_safety_manager', array['payments_and_billing_manager','fraud_analyst','general_counsel','customer_support']::text[], 'risk_and_governance_manager', 'Refund/dispute/fraud event', 'Evidence-based resolution/escalation', 'Money movement and legal commitments gated', 'completed; cancelled; superseded; failed; expired', 'yes_with_new_version'),
