  ('W20', 'Marketing content lifecycle', 'growth', 'high', 'campaign_cycle', 'content_campaign', 'Plan, create, independently review, publish and learn from marketing content against commercial objectives.', 'marketing_director', 'marketing_director', array['brand_and_creative','content_strategy_and_copy','visual_design','social_media_and_community','marketing_performance_analyst']::text[], 'ai_quality_reviewer', 'Campaign/content objective', 'Reviewed published asset and measured learning', 'Creator not sole reviewer; claims within policy', 'completed; cancelled; superseded', 'yes_with_new_version'),
