insert into public.phase_b_package_erratum (package_file, record_id, defect, evidence, correction, rationale) values
  ('PHASE_B_EXCEPTION_ESCALATION_MATRIX.csv', 'EX-006', 'row is short one cell: escalation_owner_role_id is absent, so required_response and closure_condition are each shifted one column left and the last column is empty.', 'EX-006 escalation_owner_role_id reads "Block activation/verification and correct displayed/recorded version." — a sentence, where every other one of the 50 rows holds a role id.', '{"escalation_owner_role_id":"general_counsel","required_response":"Block activation/verification and correct displayed/recorded version.","closure_condition":"Exact displayed and accepted version/hash reconcile."}'::jsonb, 'Detection owner is compliance_and_privacy_officer, so escalation cannot return to the same identity without a creator/reviewer collision. Terms text is founder-reserved (FDR-002) and the founder boundary mapping assigns "General Counsel blocks until approval" (FDR-007); general_counsel owns W28 legal/compliance verdicts and is independent of the detector.'),
  ('PHASE_B_WORKFLOW_REGISTRY.csv', 'W13', 'primary_object is "notification_delivery", which is not an object_id in PHASE_B_BUSINESS_OBJECT_REGISTRY.csv. The other 29 workflows all name a registered object.', 'The object registry holds exactly two objects governed by W13: "notification" and "notification_attempt". There is no "notification_delivery" row.', '{"primary_object":"notification"}'::jsonb, '"notification" is the canonical record W13 produces and reaches a delivered/failed/suppressed state on; "notification_attempt" is the per-try child, not the primary object.'),
  ('PHASE_B_WORKFLOW_STEP_REGISTRY.csv', 'W22-S07', 'W22 is the only workflow of the 30 with no step_type="closure", so GATE-008 (closure completeness) had no step to attach to in the product delivery workflow.', 'For the other 29 workflows, step_type="closure" and next_step_if_pass="WORKFLOW_COMPLETE" select the identical step, and no closure-typed step is ever non-final. W22-S07 "Release go/no-go" is final and points at WORKFLOW_COMPLETE.', '{"is_closure_step":true}'::jsonb, 'The closure anchor is derived as (step_type = closure OR next_step_if_pass = WORKFLOW_COMPLETE), proven equivalent on the other 29 workflows. This attaches GATE-008 to W22 rather than leaving it unenforced, keeps the declared 257-step count, and invents no work: the step, its owner and its output are unchanged.')
